{{(() => {
  const ratingsPrincipale = [
    Rating37Copy.value,
		Rating38Copy.value,
		Rating39Copy.value,
		Rating40Copy.value,
    Rating41Copy.value,
		Rating42Copy.value,
		Rating43Copy.value,
		Rating44Copy.value
  ];

  const ratingsGiroMerce = [Rating45Copy.value, Rating46Copy.value];

  const allRatings = [...ratingsPrincipale, ...ratingsGiroMerce];

  const hasInvalidRating = allRatings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: LAVORARE IN AUTONOMIA PER I TEMI DELLE PRECEDENTI SETTIMANE";
  }

  const sommaPrincipale = ratingsPrincipale.reduce((acc, val) => acc + val, 0);
  const sommaGiroMerce = ratingsGiroMerce.reduce((acc, val) => acc + val, 0);

  if (sommaPrincipale === 0 && sommaGiroMerce === 0) return "";

  return (sommaPrincipale === 24 && sommaGiroMerce >= 4)
    ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: LAVORARE IN AUTONOMIA PER I TEMI DELLE PRECEDENTI SETTIMANE"
    : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: LAVORARE IN AUTONOMIA PER I TEMI DELLE PRECEDENTI SETTIMANE";
})()
}}

